#!/usr/bin/env python3
"""Check the readability of an .excalidraw generated by build_excalidraw.py, without a browser.

Usage:
    python check_layout.py docs/architecture/architecture.excalidraw [other.excalidraw ...]

For each file it counts:
- arrow crossings (horizontal segment x vertical segment);
- overlaps (two arrows on the same line: they would read as one arrow);
- edge labels overlapping each other, or covering a node;
- arrows going through a node.

Expected: 0 overlaps, 0 hidden labels, 0 arrows through a node.
A few crossings (<= 5) are acceptable when arrows skip columns.
Exit code 1 if one of the "expected" criteria is not met.
"""
from __future__ import annotations

import json
import sys
from pathlib import Path


def check(path: Path) -> dict:
    d = json.loads(path.read_text(encoding="utf-8"))
    segs = []
    for el in d["elements"]:
        if el["type"] == "arrow" and el["id"].startswith("edge-"):
            pts = [(el["x"] + p[0], el["y"] + p[1]) for p in el["points"]]
            segs += [(el["id"], a, b) for a, b in zip(pts, pts[1:])]
    cross = overlap = 0
    for i, (ei, (x1, y1), (x2, y2)) in enumerate(segs):
        for ej, (u1, v1), (u2, v2) in segs[i + 1:]:
            if ei == ej:
                continue
            h1, h2 = abs(y1 - y2) < .5, abs(v1 - v2) < .5
            if h1 and h2 and abs(y1 - v1) < 1 and min(max(x1, x2), max(u1, u2)) - max(min(x1, x2), min(u1, u2)) > 2:
                overlap += 1
            if not h1 and not h2 and abs(x1 - u1) < 1 and min(max(y1, y2), max(v1, v2)) - max(min(y1, y2), min(v1, v2)) > 2:
                overlap += 1
            if h1 != h2:
                (hx1, hy, hx2), (vx, vy1, vy2) = ((x1, y1, x2), (u1, v1, v2)) if h1 else ((u1, v1, u2), (x1, y1, y2))
                if min(hx1, hx2) + 1 < vx < max(hx1, hx2) - 1 and min(vy1, vy2) + 1 < hy < max(vy1, vy2) - 1:
                    cross += 1
    boxes = [e for e in d["elements"] if e["id"].endswith("-lblbox")]
    nodes = [e for e in d["elements"] if e["id"].startswith("node-")]

    def ov(a, b):
        return a["x"] < b["x"] + b["width"] and b["x"] < a["x"] + a["width"] \
            and a["y"] < b["y"] + b["height"] and b["y"] < a["y"] + a["height"]

    through = sum(
        1 for _, (x1, y1), (x2, y2) in segs for n in nodes
        if min(x1, x2) < n["x"] + n["width"] - 2 and max(x1, x2) > n["x"] + 2
        and min(y1, y2) < n["y"] + n["height"] - 2 and max(y1, y2) > n["y"] + 2
    )
    return {
        "crossings": cross,
        "overlaps": overlap,
        "overlapping labels": sum(1 for i, a in enumerate(boxes) for b in boxes[i + 1:] if ov(a, b)),
        "labels on a node": sum(1 for a in boxes for b in nodes if ov(a, b)),
        "arrows through a node": through,
    }


def main() -> None:
    if len(sys.argv) < 2:
        sys.exit(__doc__)
    bad = False
    for arg in sys.argv[1:]:
        r = check(Path(arg))
        ok = (r["overlaps"] == 0 and r["overlapping labels"] == 0
              and r["labels on a node"] == 0 and r["arrows through a node"] == 0)
        bad |= not ok
        print(f"{'OK ' if ok else 'KO '} {arg}: " + " · ".join(f"{k} {v}" for k, v in r.items()))
    sys.exit(1 if bad else 0)


if __name__ == "__main__":
    main()
